import React from "react";

export function ComposentClean() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Modern 3D Scroll Experience</title>

  <!-- Three.js CDN -->

  <style>
    body {
      margin: 0;
      font-family: 'Inter', sans-serif;
      overflow: hidden;
      perspective: 1000px;
    }

    /* --- Animations originales conservées --- */
    @keyframes reveal {
      from { clip-path: inset(0 100% 0 0); }
      to { clip-path: inset(0 0 0 0); }
    }
    @keyframes textReveal {
      from { transform: translateY(100%); opacity: 0; }
      to { transform: translateY(0); opacity: 1; }
    }
    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-12px); }
    }
    @keyframes shine {
      from { transform: translateX(-100%) rotate(45deg); }
      to { transform: translateX(200%) rotate(45deg); }
    }

    .shine-effect::before {
      content: '';
      position: absolute;
      top: 0; left: 0;
      width: 100%; height: 100%;
      background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
      transform: translateX(-100%) rotate(45deg);
      z-index: 10;
    }
    .shine-effect:hover::before {
      animation: shine 1.2s ease-out;
    }

    .float-animation {
      animation: float 6s ease-in-out infinite;
    }

    .split-reveal {
      animation: reveal 1.2s cubic-bezier(0.77, 0, 0.175, 1) both;
    }
    .text-reveal-delay {
      opacity: 0;
    }

    .scroll-container {
      scroll-snap-type: y mandatory;
      height: 100vh;
      overflow-y: auto;
      overflow-x: hidden;
      -webkit-overflow-scrolling: touch;
    }
    .scroll-section {
      scroll-snap-align: start;
      height: 100vh;
      display: flex;
      transform-style: preserve-3d;
    }

    #three-canvas {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      z-index: -1;
      pointer-events: none;
    }

    .card-3d {
      transform: translateZ(30px);
      transition: transform 0.6s ease, box-shadow 0.4s ease;
    }
    .card-3d:hover {
      transform: translateZ(50px) rotateX(5deg) rotateY(5deg);
    }

    .content-mask {
      -webkit-mask-image: linear-gradient(to bottom, black 80%, transparent 100%);
      mask-image: linear-gradient(to bottom, black 80%, transparent 100%);
    }
  </style>
</head>
<body class="bg-neutral-950 text-white">
  <!-- Three.js background canvas -->
  <canvas id="three-canvas"></canvas>

  <!-- Scroll container -->
  <div class="scroll-container" id="scrollContainer">
    <!-- Section 1 -->
    <section class="scroll-section relative">
      <div class="w-full md:w-1/2 h-full relative overflow-hidden group shine-effect">
        <img src="https://images.unsplash.com/photo-1682687220742-aba13b6e50ba" 
             alt="Architectural detail" 
             class="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
        <div class="absolute inset-0 bg-gradient-to-r from-neutral-950/70 to-neutral-950/50"></div>
      </div>
      <div class="w-full md:w-1/2 h-full flex items-center justify-center p-8 bg-neutral-950">
        <div class="max-w-lg card-3d float-animation">
          <span class="text-neutral-400 tracking-wider text-sm font-mono opacity-0 text-reveal-delay" data-delay="0">01 / VISION</span>
          <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none bg-gradient-to-r from-white to-neutral-400 bg-clip-text text-transparent opacity-0 text-reveal-delay" data-delay="200">Modern Architecture</h2>
          <p class="mt-6 text-neutral-400 text-lg leading-relaxed opacity-0 text-reveal-delay" data-delay="400">Exploring the intersection of form and function in contemporary design.</p>
          <button class="mt-8 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider opacity-0 text-reveal-delay" data-delay="600">Explore More →</button>
        </div>
      </div>
    </section>

    <!-- Section 2 -->
    <section class="scroll-section relative">
      <div class="w-full md:w-1/2 h-full flex items-center justify-center p-8 bg-neutral-900">
        <div class="max-w-lg card-3d float-animation">
          <span class="text-neutral-400 tracking-wider text-sm font-mono opacity-0 text-reveal-delay" data-delay="0">02 / DESIGN</span>
          <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none bg-gradient-to-r from-white to-neutral-400 bg-clip-text text-transparent opacity-0 text-reveal-delay" data-delay="200">Urban Spaces</h2>
          <p class="mt-6 text-neutral-400 text-lg leading-relaxed opacity-0 text-reveal-delay" data-delay="400">Creating environments that inspire and transform daily life.</p>
          <button class="mt-8 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider opacity-0 text-reveal-delay" data-delay="600">Learn More →</button>
        </div>
      </div>
      <div class="w-full md:w-1/2 h-full relative overflow-hidden group shine-effect">
        <img src="https://images.unsplash.com/photo-1486406146926-c627a92ad1ab" 
             alt="Urban landscape" 
             class="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
        <div class="absolute inset-0 bg-gradient-to-l from-neutral-950/70 to-neutral-950/50"></div>
      </div>
    </section>

    <!-- Section 3 -->
    <section class="scroll-section relative">
      <div class="w-full md:w-1/2 h-full relative overflow-hidden group shine-effect">
        <img src="https://images.unsplash.com/photo-1682687220067-dced0a5865c5" 
             alt="Minimalist interior" 
             class="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
        <div class="absolute inset-0 bg-gradient-to-r from-neutral-950/70 to-neutral-950/50"></div>
      </div>
      <div class="w-full md:w-1/2 h-full flex items-center justify-center p-8 bg-neutral-950">
        <div class="max-w-lg card-3d float-animation">
          <span class="text-neutral-400 tracking-wider text-sm font-mono opacity-0 text-reveal-delay" data-delay="0">03 / SPACE</span>
          <h2 class="mt-4 text-5xl md:text-7xl font-bold leading-none bg-gradient-to-r from-white to-neutral-400 bg-clip-text text-transparent opacity-0 text-reveal-delay" data-delay="200">Interior Flow</h2>
          <p class="mt-6 text-neutral-400 text-lg leading-relaxed opacity-0 text-reveal-delay" data-delay="400">Harmonizing space and light to create immersive experiences.</p>
          <button class="mt-8 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-full text-sm font-medium transition-all duration-300 hover:tracking-wider opacity-0 text-reveal-delay" data-delay="600">Discover More →</button>
        </div>
      </div>
    </section>
  </div>

  <!-- Navigation dots -->
  <div class="fixed right-8 top-1/2 -translate-y-1/2 flex flex-col gap-4 z-50">
    <button class="w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-all hover:scale-150"></button>
    <button class="w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-all hover:scale-150"></button>
    <button class="w-3 h-3 rounded-full bg-white/20 hover:bg-white transition-all hover:scale-150"></button>
  </div>


</body>
</html>" }} />
  );
}
